package com.contextgraph.controller; import com.contextgraph.service.GraphService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/graph") public class GraphController{final GraphService g;public GraphController(GraphService g){this.g=g;}@GetMapping("/nodes")public Object nodes(Authentication a){return g.nodes(a.getName());}@GetMapping("/relations/{id}")public Object relations(@PathVariable Long id){return g.relations(id);}}